<template><nav class="app-menu-bar" data-app-menu role="menubar" aria-label="应用菜单"><el-dropdown ref="dropdowns" v-for="group in menuGroups" :key="group.id" trigger="click" :teleported="true" @command="execute"><button class="menu-trigger" :data-testid="`menu-${group.id}`" role="menuitem" type="button">{{group.label}}</button><template #dropdown><el-dropdown-menu :data-testid="`menu-popup-${group.id}`"><el-dropdown-item v-for="command in group.commands" :key="command.id" :command="command.id" :disabled="!enabled(command)" :title="reason(command)"><span>{{command.label}}</span><kbd v-if="command.shortcut">{{command.shortcut}}</kbd></el-dropdown-item></el-dropdown-menu></template></el-dropdown></nav></template>
<script setup lang="ts">import {onBeforeUnmount,onMounted,ref} from 'vue';import {menuGroups,type AppCommand,type CommandId} from '@/config/menuCommands';import {useEditorStore} from '@/stores/editor';const store=useEditorStore(),dropdowns=ref<Array<{handleClose:()=>void}>>([]);const emit=defineEmits<{command:[id:CommandId]}>();function enabled(c:AppCommand){if(c.disabledReason)return false;if(c.needsModel&&!store.scene.robotId)return false;if(c.needsSelection&&!store.selectedId)return false;if(c.history==='undo')return store.scene.history.canUndo;if(c.history==='redo')return store.scene.history.canRedo;return true}function reason(c:AppCommand){return c.disabledReason||(c.needsModel&&!store.scene.robotId?'请先导入模型':c.needsSelection&&!store.selectedId?'请先选择对象':'')}function execute(id:CommandId){emit('command',id)}function key(event:KeyboardEvent){if(event.key==='Escape')dropdowns.value.forEach(item=>item.handleClose())}onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>window.removeEventListener('keydown',key))</script>
<style scoped>.app-menu-bar{display:flex;gap:4px;position:relative;z-index:100;pointer-events:auto}.menu-trigger{border:0;background:transparent;color:#94a8ba;padding:8px 9px;border-radius:4px;cursor:pointer;-webkit-app-region:no-drag}.menu-trigger:hover,.menu-trigger:focus-visible{background:#203344;color:#e1edf5;outline:none}kbd{margin-left:28px;color:#8296a6;font:11px Consolas}</style>
